function headerTip(x,y,w,h,body,tip){return `<g tabindex="0" role="note" data-tip="${esc(tip)}"><rect x="${x}" y="${y}" width="${w}" height="${h}" fill="transparent" pointer-events="all"/>${body}</g>`}
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let showBufferLife=true;
let ci=4,step=0,view={x:24,y:32,s:.75},prior=null,selectedLife=null,viewers=[];const current=()=>DATA.cases[ci],colors={activation:'#B1EF6B',weight:'#BCA0F3',aggregate:'#F2C45F'};
const kb=n=>n<1024?n+' B':(n/1024).toFixed(2).replace(/\.?0+$/,'')+' KiB';
function text(x,y,t,size=14,color='#ddd'){return `<text x="${x}" y="${y}" font-size="${size}" fill="${color}">${esc(t)}</text>`}
const taskCache=new Map();function taskImage(label,color){const key=label+color;if(taskCache.has(key))return taskCache.get(key);const c=document.createElement('canvas');c.width=136;c.height=76;const ctx=c.getContext('2d');ctx.scale(2,2);PtoSwimlaneTaskPattern.drawTaskBar(ctx,{x:0,y:0,width:68,height:38,task:{label},baseColor:color,fontFamily:'monospace'});const image=c.toDataURL();taskCache.set(key,image);return image}
function transform(){$('world').setAttribute('transform',`translate(${view.x} ${view.y}) scale(${view.s})`);$('scale').textContent=Math.round(view.s*100)+'%'}
function defaultView(){view={x:24,y:32,s:.75};transform()}
function fit(){const c=current(),trackHeight=[...new Set(c.life.map(l=>l.buffer))].reduce((h,b)=>h+(1+Math.max(...c.life.filter(l=>l.buffer===b).map(l=>l.displayBand)))*46+14,0);view={x:20,y:20,s:Math.min(1,($('main').clientWidth-40)/(Math.max(900,c.events.length*76)+245),($('main').clientHeight-40)/(690+trackHeight+90))};transform()}
function show(title,body,kind='detail'){$('panelTitle').textContent=title;$('panelBody').innerHTML=body;$('sidePanel').dataset.kind=kind;$('sidePanel').hidden=false}
function sourceLink(line,kind='kernel'){return `${DATA.repo}/blob/${DATA.revision}/${DATA.sources[kind].path}#L${line}`}
function snippet(line,kind='kernel'){const lines=DATA.sources[kind].text.split('\n');return `<p><a href="${sourceLink(line,kind)}" target="_blank" rel="noopener" data-tip="打开固定版本 GitHub 源码">${esc(DATA.sources[kind].path)}:${line} ↗</a></p><pre>${esc(lines.slice(Math.max(0,line-4),line+5).map((s,i)=>`${Math.max(1,line-3)+i}  ${s}`).join('\n'))}</pre>`}
function select(i,fromQueue=false){if(!fromQueue)selectedLife=null;step=Math.max(0,Math.min(current().events.length-1,i));draw();sync();if(!$('sidePanel').hidden&&$('sidePanel').dataset.kind==='inspect'){const q=$('question')?.value;inspectObject(q)}if(!fromQueue){const e=current().events[step],x=220+(step+.5)*76;if(view.x+x*view.s>$('main').clientWidth-25||view.x+x*view.s<25){view.x=100-x*view.s;transform()}}}
function draw(){const c=current(),events=c.events,x0=220,cw=76,ww=Math.max(900,events.length*cw),ys=[143,225,307,389],my=500;let s='';
 s+=text(20,10,`${c.whole?'ProcessWholeRows':'ProcessChunkedRows'} · FP16`,18);s+=text(20,40,`core ${c.core} · rows [${c.start}, ${c.end}) · ${c.origin==='public'?'公开用例':'源码边界配置'}`,14,'#bbb');s+=text(20,69,c.whole?`前 ${c.shown.length} 行 / ${Math.max(0,c.end-c.start)} 行 · align ${c.aligned}`:`首行 · ${Math.ceil(c.shape[1]/c.tile)} chunks · tile ${c.tile}`,13,'#bbb');
 s+=`<g tabindex="0" data-tip="源码步骤顺序，等宽排列；不表示耗时或实际重叠。箭头仅显示当前事件的显式数据依赖。"><rect x="220" y="48" width="${ww}" height="60" fill="transparent" pointer-events="all"/></g>`;
 s+=headerTip(12,80,208,36,text(24,105,'指令执行',18),'按源码步骤排列；横向位置表示执行顺序，不表示实际耗时。');
 ['MTE2','Vector','MTE3','Scalar / Sync'].forEach((n,k)=>{s+=`<rect x="12" y="${ys[k]-22}" width="${ww+220}" height="82" fill="${k%2?'#1b1b1b':'#141414'}"/>`+headerTip(12,ys[k]-22,208,82,text(24,ys[k]+12,n,15)+text(24,ys[k]+34,['GM → UB','Add / RMSNorm','UB → GM','顺序 / 等待 / 释放'][k],13,'#bbb'),['MTE2：从全局内存 GM 搬入核内 UB。','Vector：执行残差加法、平方和归约与归一化。','MTE3：将 UB 输出写回全局内存 GM。','Scalar / Sync：源码中的标量控制、同步等待与队列归还；FreeTensor 不释放整个 UB 预留区。'][k])});
 events.forEach((e,i)=>{const x=x0+i*cw,on=i===step,color=on?(e.lane===1?'#0BB48E':e.lane===0||e.lane===2?'#FFE300':'#d4d4d4'):'#55595d';s+=`<rect x="${x}" y="78" width="${cw}" height="28" fill="${on?'#d4d4d4':'transparent'}"/>`+text(x+30,98,i+1,12,on?'#111':'#bbb');const label=e.kind==='weight'?'γ':e.kind==='input'||e.kind==='reread'?'X+R':e.kind==='reduce'?'Σ/NR':e.kind==='norm'?'×γ':e.kind==='write'?'→GM':e.kind==='free'?'Free':e.kind==='wait'?'Wait':e.kind==='cast'?'Cast':e.kind==='add'?'Add':e.kind==='window'?'…':'Drain';s+=`<g data-event="${i}" role="button" tabindex="0" aria-label="${esc(e.label)}" data-tip="${esc(e.label)} · 源码 L${e.line}"><image x="${x+4}" y="${ys[e.lane]}" width="68" height="38" href="${taskImage(label,color)}"/></g>`});
 const selected=events[step];if(selected)for(const pid of selected.parents){const from=events.find(e=>e.id===pid);if(!from)continue;const x=x0+(from.index+1)*cw-4,end=x0+step*cw+4,y=ys[from.lane]+19,ey=ys[selected.lane]+19;s+=`<path d="M${x} ${y}H${end-5}V${ey}H${end}" fill="none" stroke="#ddd" stroke-width="1.5" marker-end="url(#arrow)"/>`}
 s+=headerTip(12,my-52,400,40,text(24,my-25,'UB · 数据使用区间',18),'UB 是核内统一缓冲。下方显示缓冲中的数据使用区间；队列槽归还不等于整块缓冲释放。');const buffers=[...new Set(c.life.map(l=>l.buffer))];let by=my;buffers.forEach((b,k)=>{const ls=c.life.filter(l=>l.buffer===b),bands=1+Math.max(...ls.map(l=>l.displayBand)),h=bands*60;s+=`<rect x="12" y="${by-5}" width="${ww+220}" height="${h}" fill="${k%2?'#1b1b1b':'#141414'}"/>`;s+=headerTip(12,by-5,208,h,text(24,by+31,b,12,'#ccc'),b+ '：'+({inQueX:'输入 X 队列',inQueRes:'残差 R 队列',weightHalfBuf:'FP16 缩放权重 γ',weightFp32Buf:'转换为 FP32 的缩放权重 γ'}[b]||(/resOut/.test(b)?'残差加法输出缓冲':'归一化输出缓冲'))+'；横向区间对应上方源码步骤。');for(const l of ls){const y=by+7.5+l.displayBand*60,on=l.id===selectedLife||l.start<=step&&step<l.end,w=(l.end-l.start)*cw-8,col=on?colors[l.role]:'#858585';s+=`<g data-event="${l.start}" data-life="${esc(l.id)}" role="button" tabindex="0" data-tip="${esc(l.name)} · ${kb(l.size)} · ${esc(l.semantics)}">${GridTensor.render(x0+l.start*cw+4,y,w,l.name,col,l.id)}</g>`}by+=h});
 if(selected)s+=`<path d="M${x0+(step+.5)*cw} 108V${by}" stroke="#aaa" stroke-dasharray="2 5" opacity=".4"/>`;
 s+=text(20,by+32,selected?`当前步骤 ${step+1} · ${selected.label}`:'当前核无有效行',16);s+=text(20,by+60,`全张量完整执行：X / R 请求各 ${kb(c.requestBytes.x)} · 核内缓冲预留 ${kb(c.reserved)}`,14,'#bbb');$('world').innerHTML=s;transform();$('case').textContent=c.shape.join(' × ')+' / FP16';$('coreConfig').textContent=`${c.cores} AIV · 核 ${c.core}`;$('count').textContent=c.findings.length;$('reuse').setAttribute('aria-pressed',showBufferLife);}
function sync(){syncHardware();for(const v of viewers){const candidates=v.data.tensors.filter(t=>t.allocTick<=step&&step<t.freeTick),e=current().events[step];const active=candidates.find(t=>t.id===selectedLife)||candidates.find(t=>{const l=current().life.find(l=>l.id===t.id);return l?.row===e?.row&&l?.chunk===e?.chunk})||candidates[0];v.state.selected=active?.id||null;v.detailPopover.hidden=true;v.tip.style.display='none';v.draw()}}
function memory(){viewers.forEach(v=>v.destroy());viewers=[];const c=current(),buffers=[...new Set(c.life.map(l=>l.buffer))];$('columns').innerHTML=buffers.map((b,i)=>`<section class="column"><h3>${esc(b)}<small>预留 ${kb(c.capacities[b])}</small></h3><div class="plot" id="q${i}"></div></section>`).join('');buffers.forEach((b,i)=>{const tensors=c.life.filter(l=>l.buffer===b).map((l,j,ls)=>({id:l.id,name:l.name,buffer:b,offset:l.displayOffset,size:l.size,allocTick:l.start,freeTick:l.end,kind:'temp',reuseOf:null,reusedBy:[],eventIndex:l.start,srcFile:DATA.sources.kernel.path,srcLineStart:l.line,srcLineEnd:l.endLine,code:DATA.sources.kernel.text.split('\n').slice(l.line-1,l.line+2).join('\n')}));const v=PtoMemoryReuseViewer.render($('q'+i),{kernel:c.whole?'ProcessWholeRows':'ProcessChunkedRows',ticks:c.ticks,buffers:[{name:b,capacity:c.capacities[b]}],tensors,sourceFiles:[]},{initialBuffer:b});v.root.querySelectorAll('[title]').forEach(el=>el.removeAttribute('title'));viewers.push(v)});requestAnimationFrame(()=>{viewers.forEach(v=>v.resize());sync()})}
$('memory').addEventListener('pto-memory-reuse-tensor-select',e=>{const l=current().life.find(l=>l.id===e.detail.tensor?.id);if(l){selectedLife=l.id;select(l.start,true)}});
function change(i){const kind=$('sidePanel').dataset.kind,open=!$('sidePanel').hidden;ci=i;step=0;selectedLife=null;draw();memory();defaultView();syncHardware();if(open&&kind==='audit')auditList();else if(open&&kind==='inspect')inspectObject();else if(open)$('sidePanel').hidden=true;if(!$('memoryHelp').hidden)memoryHelp()}
function split(on){showBufferLife=on;document.body.classList.toggle('split',on);if(on){prior={...view};memory();defaultView()}else if(prior){view={...prior};transform()}draw();}
$('reuse').onclick=()=>split(!showBufferLife);$('closeMemory').onclick=()=>split(false);
$('case').onclick=()=>{const m=$('menu');m.innerHTML=DATA.cases.map((c,i)=>`<button role="option" data-case="${i}" aria-selected="${i===ci}" data-tip="${c.origin==='public'?'公开测试用例':'新增源码边界配置'}">${c.shape.join(' × ')} FP16 ${c.origin==='public'?'':'· 边界'}</button>`).join('');m.hidden=!m.hidden;$('case').setAttribute('aria-expanded',String(!m.hidden))};
