function auditList(){const c=current();show('源码核查 · '+c.findings.length,c.findings.map(f=>`<section class="finding" data-finding="${esc(f.id)}"><h3>${esc(f.title)}</h3><p>${esc(f.text)}</p><div class="finding-actions"><button data-locate="${esc(f.id)}" data-tip="定位关联事件，保持核查列表">定位主体</button><button class="primary" data-investigate="${esc(f.id)}" data-tip="携带当前配置、问题和证据继续调查">继续调查 ↗</button></div><p><a href="${sourceLink(f.line)}" target="_blank" rel="noopener" data-tip="打开固定版本源码证据">Kernel:${f.line} ↗</a></p></section>`).join(''),'audit')}
$('audit').onclick=()=>{if(!$('sidePanel').hidden&&$('sidePanel').dataset.kind==='audit')$('sidePanel').hidden=true;else auditList()};
function locateFinding(f){const c=current(),i=c.events.findIndex(v=>v.line===f.line||v.line>=f.line&&v.line<f.line+8);select(i<0?0:i);$('panelBody').querySelectorAll('[data-finding]').forEach(el=>el.classList.toggle('selected',el.dataset.finding===f.id))}
function handoff(question){const c=current(),e=c.events[step];return {caseId:c.id,shape:c.shape,dtype:'FP16',revision:DATA.revision,repo:DATA.repo,event:e,reservations:c.reservations,instructionAccesses:c.instructionAccesses,accessEvidence:c.accessEvidence,intervals:c.life.filter(l=>l.start<=step&&step<l.end),question,source:e?sourceLink(e.line):null,unconfirmed:['NPU numerical correctness','physical TQue slots','actual timing and overlap']}}
function inspectObject(question='请核对当前对象的输入、缓冲生命周期和源码，给出最小上板验证方案；区分源码关系与设备观测。'){const c=current(),e=c.events[step];show('当前选择',e?`<h3>${esc(e.label)}</h3><p class="help">${esc(e.id)}</p><p>行 ${e.row??'—'} · chunk ${e.chunk??'—'} · ${['MTE2','Vector','MTE3','Scalar / Sync'][e.lane]}</p>${snippet(e.line)}<label class="question">继续调查<textarea id="question" aria-label="当前对象的调查问题" data-tip="编辑交给后续调查的问题">${esc(question)}</textarea></label><details><summary data-tip="展开当前选择的结构化证据">交接预览</summary><pre id="handoffPreview">${esc(JSON.stringify(handoff(question),null,2))}</pre></details><div class="copy-actions"><button id="copyEvidence" class="primary" data-tip="复制当前问题与对象证据">复制证据</button><button id="exportEvidence" data-tip="导出当前选择为 JSON">导出 JSON</button></div><div id="copyStatus" class="status" role="status"></div>`:'当前核无有效行','inspect')}
$('inspect').onclick=()=>{if(!$('sidePanel').hidden&&$('sidePanel').dataset.kind==='inspect')$('sidePanel').hidden=true;else inspectObject()};
$('source').onclick=()=>{if(!$('sidePanel').hidden&&$('sidePanel').dataset.kind==='source')$('sidePanel').hidden=true;else show('固定提交 · '+DATA.revision.slice(0,12),snippet(current().events[step]?.line||1),'source')};
async function copyText(value,status){try{await navigator.clipboard.writeText(value);status.textContent='已复制'}catch{status.textContent='复制失败，请从展开的预览中手动复制。'}}
$('panelBody').onclick=e=>{const locate=e.target.closest('[data-locate]'),investigate=e.target.closest('[data-investigate]');if(locate||investigate){const id=locate?.dataset.locate||investigate.dataset.investigate,f=current().findings.find(f=>f.id===id);if(!f)return;locateFinding(f);if(investigate)inspectObject(`针对发现「${f.title}」继续调查。${f.text} 固定源码证据：${sourceLink(f.line)}。请设计最小验证实验，不修改上游算子。`)}if(e.target.closest('#copyEvidence'))copyText(JSON.stringify(handoff($('question').value),null,2),$('copyStatus'));if(e.target.closest('#exportEvidence')){const u=URL.createObjectURL(new Blob([JSON.stringify(handoff($('question').value),null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='fused-rmsnorm-selection.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}};
$('panelBody').addEventListener('input',e=>{if(e.target.id==='question')$('handoffPreview').textContent=JSON.stringify(handoff(e.target.value),null,2)});
function memoryHelp(){const c=current();$('memoryHelpBody').innerHTML=`<div class="legend-row"><span><i style="background:#858585"></i>未关联</span><span><i style="background:#B1EF6B"></i>X / R / 输出</span><span><i style="background:#BCA0F3"></i>γ</span><span><i class="peak"></i>区间字节量</span></div><p>InitBuffer 合计 <b>${kb(c.reserved)}</b>。包括两个分支统一预留的缓冲，不等于图中所展示区间的峰值。</p><p>纵向共用源码步骤；横向为各 buffer 的逻辑占位与尺寸。并存区间分轨，左右视图使用同一份排布。逻辑轨道和 offset 不代表 TQue 物理槽或真实地址。</p><p>TQue 区间为源码中的队列使用范围；FreeTensor 归还队列槽，不释放整个 UB 预留区。显式输出 TBuf 区间表示数据写入到复用等待或视窗截断，并非 TBuf 存储释放。白线累加本列当前显示区间的字节数；TBuf 列表示数据使用区间总量，不是重新申请量或物理 UB 占用。整行显示前3行及下一行预取；截断不表示已释放。</p><p>缓冲预留、数据有效和指令访问分别记录。当前未采集指令访存；源码步骤不证明数据写入已完成，也不能把最后一次读取当作释放。真实地址和有效时间仍待编译与仿真证据。</p>`;}
$('memoryInfo').onclick=()=>{memoryHelp();$('memoryHelp').hidden=!$('memoryHelp').hidden;$('memoryInfo').setAttribute('aria-expanded',String(!$('memoryHelp').hidden))};$('memoryHelpClose').onclick=()=>{$('memoryHelp').hidden=true;$('memoryInfo').setAttribute('aria-expanded','false')};
const PROMPT='使用 ai-infra-investigation，读取本页导出的 Fused Add RMSNorm 选择和固定提交 7729cdf7bc37d77bd3c82448414b77cea3e96637。核对 ProcessWholeRows / ProcessChunkedRows 的 FP16 与 FP32 Add 差别、下一行预取、输入队列和显式奇偶输出缓冲的生命周期。区分源码请求、逻辑排布与物理槽；提出 H=4096/4097 的最小正确性与 profiling 对照实验。不修改上游实现，不套用 950 的性能标定到 910B。';
$('info').onclick=()=>{$('usageBody').innerHTML=`<h3>价值</h3><p>这是一轮独立开发者实现的迁移验证：从 Add + RMSNorm 的 Host 与 Kernel 重建执行顺序、输入预取、输出复用和尾块关系，检查已有 RMSNorm 可视化能否保留真实实现的差异。</p><p>当前来源是 <a href="${DATA.repo}/tree/${DATA.revision}" target="_blank" rel="noopener" data-tip="查看固定版本的独立开发者项目">llrnb666-arch / HPC101-AscendC-FusedRMSNorm ↗</a>，提交 ${DATA.revision.slice(0,12)}，目标 Ascend 910B。源码不是 CANNBot 自带验证样例。</p><h3>使用</h3><p>左下切换五个公开用例与两个新增边界配置。选择任务或 Tensor 查看关联区间；点击下方缓冲区间反向定位任务。拖动画布平移，滚轮围绕光标缩放。缓冲生命周期在右侧抽屉查看，与主体选择双向联动。</p><p>“硬件对照”打开 910B 局部架构，随当前事件联动；展开规格可核对硬件来源与 UB 申请量。右上依次为核查、当前选择、源码、教程。核查定位保持完整列表；“继续调查”携带配置、发现与证据进入当前选择，可编辑问题、复制或导出。横轴区域悬停查看尺度说明。</p><div class="prompt"><button id="promptCopy" class="icon" aria-label="复制继续调查 prompt" data-tip="复制可直接使用的调查 prompt"><svg viewBox="0 0 24 24"><rect x="8" y="8" width="12" height="13" rx="2"/><path d="M15 8V5H3v13h5"/></svg></button><pre id="usagePrompt">${esc(PROMPT)}</pre></div><div id="promptStatus" class="status" role="status"></div><h3>扩展</h3><p>当前覆盖五个公开配置，以及为分块覆盖补充的 [4,4097]、[4,8193]。后两个是本轮源码边界检查，尚无设备运行结果。换源码版本或算子时，需要重新核对分支、对象关系、申请释放和证据，不能只替换 shape。</p><h3>方法、Skill 与数据来源</h3><p>本轮使用 ai-infra-investigation 组织表达约定与视图职责，operator-mapping-investigation 建立固定版本源码模型；界面复用 RMSNorm Pattern 的 Tensor、任务和 Memory Reuse Viewer 渲染器，以及 design-spatial-systems-ui 的 liquid 控件资源。模型是手工核对的源码适配器，不是自动 C++ 解析器。</p><p>本例没有调用限定 950 的 <a href="https://github.com/hicann/cannbot-skills/tree/f305e200aa4b1e1fed73cd21ff1f083b8df25a1e/ops/ops-theoretical-performance-estimation" target="_blank" rel="noopener" data-tip="查看 CANNBot 性能引擎的适用范围">CANNBot ops-theoretical-performance-estimation ↗</a>。因此本页没有 CANNBot 定量性能结果，也没有本机 NPU 实测。图中事件、字节量和生命周期来自 Host / Kernel 的静态重建；源码步骤不表示实测时长或重叠。</p>`;$('promptCopy').onclick=()=>copyText(PROMPT,$('promptStatus'));$('usageWindow').showModal()};
$('usageClose').onclick=()=>$('usageWindow').close();$('usageWindow').addEventListener('click',e=>{if(e.target===$('usageWindow'))$('usageWindow').close()});$('panelClose').onclick=()=>$('sidePanel').hidden=true;
let panelDrag=null;$('sidePanel').querySelector('.head').onpointerdown=e=>{if(e.target.closest('button'))return;const r=$('sidePanel').getBoundingClientRect();panelDrag={x:e.clientX,y:e.clientY,left:r.left,top:r.top};e.currentTarget.setPointerCapture(e.pointerId)};window.addEventListener('pointermove',e=>{if(!panelDrag)return;const p=$('sidePanel');p.style.left=Math.max(8,Math.min(innerWidth-p.offsetWidth-8,panelDrag.left+e.clientX-panelDrag.x))+'px';p.style.top=Math.max(8,Math.min(innerHeight-80,panelDrag.top+e.clientY-panelDrag.y))+'px';p.style.right='auto';p.style.bottom='auto'});window.addEventListener('pointerup',()=>panelDrag=null);
function closeMenu(){$('menu').hidden=true;$('case').setAttribute('aria-expanded','false')}$('case').setAttribute('aria-haspopup','listbox');$('case').setAttribute('aria-expanded','false');$('menu').onkeydown=e=>{const bs=[...$('menu').querySelectorAll('button')],i=bs.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();bs[e.key==='Home'?0:e.key==='End'?bs.length-1:(i+(e.key==='ArrowDown'?1:-1)+bs.length)%bs.length]?.focus()}if(e.key==='Escape'){closeMenu();$('case').focus()}};
$('plus').onclick=()=>{view.s=Math.min(2,view.s*1.15);transform()};$('minus').onclick=()=>{view.s=Math.max(.2,view.s/1.15);transform()};$('fit').onclick=fit;
let drag=null;$('main').onpointerdown=e=>{if(e.target.closest('[data-event]'))return;drag={x:e.clientX,y:e.clientY,vx:view.x,vy:view.y};$('main').setPointerCapture(e.pointerId)};$('main').onpointermove=e=>{if(drag){view.x=drag.vx+e.clientX-drag.x;view.y=drag.vy+e.clientY-drag.y;transform()}};$('main').onpointerup=()=>drag=null;
$('main').addEventListener('wheel',e=>{e.preventDefault();const r=$('main').getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,ns=Math.max(.2,Math.min(2,view.s*Math.exp(-e.deltaY*.001)));view.x=x-(x-view.x)*ns/view.s;view.y=y-(y-view.y)*ns/view.s;view.s=ns;transform()},{passive:false});
$('canvas').onclick=e=>{const g=e.target.closest('[data-event]');if(g){selectedLife=g.dataset.life||null;select(+g.dataset.event,!!g.dataset.life)}};$('canvas').onkeydown=e=>{const g=e.target.closest('[data-event]');if(g&&['Enter',' '].includes(e.key)){e.preventDefault();selectedLife=g.dataset.life||null;select(+g.dataset.event,!!g.dataset.life)}};
const tip=$('tip');function tooltip(el,x,y){if(!el?.dataset.tip){tip.hidden=true;return}tip.textContent=el.dataset.tip;tip.hidden=false;tip.style.left=Math.max(8,Math.min(x+12,innerWidth-tip.offsetWidth-12))+'px';tip.style.top=Math.max(8,Math.min(y+18,innerHeight-tip.offsetHeight-12))+'px'}document.addEventListener('pointermove',e=>tooltip(e.target.closest('[data-tip]'),e.clientX,e.clientY));document.addEventListener('focusin',e=>{const r=e.target.getBoundingClientRect();tooltip(e.target.closest('[data-tip]'),r.left,r.bottom)});document.addEventListener('focusout',()=>tip.hidden=true);document.addEventListener('click',e=>{if(!e.target.closest('#menu,#case'))closeMenu()});window.addEventListener('resize',()=>{transform();viewers.forEach(v=>v.resize())});draw();defaultView();memory();

const hw={ready:false,preset:null,overlay:null};
function fitHardware(){if(!hw.ready||$('hardwarePanel').hidden)return;const host=$('architectureHost'),vp=$('hardwareMiniViewport');host.style.transform='none';const r=host.getBoundingClientRect(),core=host.querySelector('#mem950-aiv1').getBoundingClientRect(),gm=host.querySelector('[data-mem950-node="rail:GM"]').getBoundingClientRect(),x=gm.left-r.left-12,y=core.top-r.top-12,w=core.right-gm.left+24,h=core.height+24,z=Math.min(vp.clientWidth/w,vp.clientHeight/h);host.style.transform=`matrix(${z},0,0,${z},${(vp.clientWidth-w*z)/2-x*z},${(vp.clientHeight-h*z)/2-y*z})`;hw.overlay.update()}
function syncHardware(){if($('hardwarePanel').hidden)return;const helper=window.PtoMemoryArchitecturePattern,host=$('architectureHost');if(!hw.ready){hw.preset=JSON.parse(JSON.stringify(helper.resolvePreset('ascend910b')));hw.preset.details=[];hw.preset.notes=[];hw.preset.cores=hw.preset.cores.filter(c=>c.kind==='aiv');hw.preset.routes=hw.preset.routes.filter(r=>['l2-to-aiv1','aiv1-to-l2','l2-to-aiv1-scalar'].includes(r.id));helper.renderArchitecture(host,hw.preset);hw.overlay=helper.createRouteOverlay(host,hw.preset);hw.overlay.render();host.querySelectorAll('[title],[tabindex],[role]').forEach(el=>{el.removeAttribute('title');el.removeAttribute('tabindex');el.removeAttribute('role')});hw.ready=true}const e=current().events[step],ub='#mem950-aiv1 [data-aiv-node="buffer:UB"]',vec='#mem950-aiv1 [data-aiv-node="vector:Vector"]',scalar='#mem950-aiv1 [data-aiv-node="scalar:Scalar"]',rails=['[data-mem950-node="rail:GM"]','[data-mem950-node="rail:L2"]'];const lane=e?.lane;host.dataset.lane=String(lane);helper.setPathFocus(host,hw.preset,{selectors:lane===0||lane===2?[...rails,ub]:lane===1?[ub,vec]:[scalar,ub],routes:lane===0?['l2-to-aiv1']:lane===2?['aiv1-to-l2']:[]});$('hardwareReadout').textContent=`步骤 ${step+1} · ${e?.label||'无事件'}　${['GM → MTE2 → UB','UB ↔ Vector','UB → MTE3 → GM','Scalar / 核内同步'][lane]||''} · InitBuffer ${kb(current().reserved)}`;requestAnimationFrame(fitHardware)}
function toggleHardware(on){$('hardwarePanel').hidden=!on;$('hardwareButton').setAttribute('aria-pressed',String(on));if(on)syncHardware()}
$('hardwareButton').onclick=()=>toggleHardware($('hardwarePanel').hidden);$('hardwareClose').onclick=()=>toggleHardware(false);new ResizeObserver(fitHardware).observe($('hardwareMiniViewport'));window.addEventListener('keydown',e=>{if(e.key==='Escape')toggleHardware(false)});
let hwDrag=null;$('hardwarePanel').querySelector('.head').onpointerdown=e=>{if(e.target.closest('button'))return;const r=$('hardwarePanel').getBoundingClientRect();hwDrag={x:e.clientX,y:e.clientY,left:r.left,top:r.top};e.currentTarget.setPointerCapture(e.pointerId)};window.addEventListener('pointermove',e=>{if(!hwDrag)return;const p=$('hardwarePanel');p.style.left=Math.max(8,Math.min(innerWidth-p.offsetWidth-8,hwDrag.left+e.clientX-hwDrag.x))+'px';p.style.top=Math.max(8,Math.min(innerHeight-80,hwDrag.top+e.clientY-hwDrag.y))+'px';p.style.bottom='auto'});window.addEventListener('pointerup',()=>hwDrag=null);
